def minPath(grid, k):
    from heapq import heappop, heappush

    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    min_heap = []

    # Initialize the heap with all starting points
    for i in range(N):
        for j in range(N):
            heappush(min_heap, (grid[i][j], [(grid[i][j])], i, j))

    while min_heap:
        value, path, x, y = heappop(min_heap)

        if len(path) == k:
            return path

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < N and 0 <= ny < N:
                heappush(min_heap, (value + grid[nx][ny], path + [grid[nx][ny]], nx, ny))

